"""Collect locked Cargo dependencies' upstream notices for binary distributions.

Run after updating Cargo.lock. Uses Cargo's own dependency metadata and preserves
license text verbatim, deduplicating identical texts across crates.
"""

from collections import defaultdict
import json
from pathlib import Path
import subprocess

root = Path(__file__).resolve().parents[1]
metadata = json.loads(subprocess.check_output(
    ["cargo", "metadata", "--locked", "--offline", "--format-version", "1"], cwd=root,
))
texts = defaultdict(list)
lines = [
    "# Third-party notices\n",
    "Generated by `python scripts/collect_licenses.py` from `Cargo.lock`.\n",
    "Includes native/WASM runtime and build dependencies. MSRC itself is MIT licensed.\n",
    "| Crate | Version | Declared license |\n| --- | --- | --- |",
]
for package in sorted(metadata["packages"], key=lambda p: (p["name"], p["version"])):
    if package["source"] is None:
        continue
    label = f'{package["name"]} {package["version"]}'
    lines.append(f'| {package["name"]} | {package["version"]} | {package["license"]} |')
    directory = Path(package["manifest_path"]).parent
    notices = sorted(p for p in directory.iterdir()
                     if p.is_file() and p.name.startswith(("LICENSE", "NOTICE", "COPYING")))
    if not notices:
        raise SystemExit(f"Review missing license files for {label}")
    for notice in notices:
        texts[notice.read_text(encoding="utf-8").strip()].append(f"{label}/{notice.name}")
for contents, owners in texts.items():
    lines.extend(["", "## " + ", ".join(owners), "", "```text", contents, "```"])
lines.extend(["", "## Replay preprocessing source adaptations", "", "```text",
              (root / "src/preprocess/LICENSE-THIRD-PARTY").read_text(encoding="utf-8").strip(), "```"])
(root / "THIRD_PARTY_NOTICES.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"Collected {len(texts)} distinct upstream notice texts")
